  let prev = 0;
  for (let i = 1; i <= n; i++) {
    const t = (maxLen * i) / n;
    if (!inside(t)) {
      let lo = prev, hi = t;
      for (let k = 0; k < 10; k++) {
        const m = 0.5 * (lo + hi);
        if (inside(m)) lo = m; else hi = m;
      }
      return 0.5 * (lo + hi);
    }
    prev = t;
  }
  return maxLen;
}

