  const gp = (i, j) => { const k = (i * cols + j) * 3; return [P[k], P[k + 1], P[k + 2]]; };
  const gn = (i, j) => { const k = (i * cols + j) * 3; return [N[k], N[k + 1], N[k + 2]]; };

