    for (let j = jt - 1; j >= 0; j--) QD[i * cols + j] = QD[i * cols + j + 1] + Math.hypot(...sub(gp(i, j), gp(i, j + 1)));
  }

  // ---------------------------------------------------------------------------
  // Mesh arrays (object space)
