    for (let j = 0; j <= NV; j++) {
      const idx = i * cols + j;
      position.set(toObject(gp(i, j)), idx * 3);
      normal.set(dirToObject(gn(i, j)), idx * 3);
      uv[idx * 2] = sList[i] / S_END;
      uv[idx * 2 + 1] = j / NV;
    }
