// Fins: pleated membrane meshes with individual rays + a shared texture atlas.
import { section, topY, botY, surfaceAt, toObject, dirToObject } from './anatomy.mjs';
import { perlin3, fbm3, hash01, clamp, mix, smoothstep } from '../lib/noise.mjs';

const DEG = Math.PI / 180;
const nrm = (a) => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const mul = (a, k) => [a[0] * k, a[1] * k, a[2] * k];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];

export const ATLAS = 2048;
const INSET = 6;

function inPlaneBend(dir, normal) {
  // component of the posterior axis (+s) perpendicular to the ray, inside the fin plane
  let b = sub([1, 0, 0], mul(dir, dot([1, 0, 0], dir)));
  b = sub(b, mul(normal, dot(b, normal)));
  const l = Math.hypot(...b);
  return l < 1e-5 ? [0, 0, 0] : mul(b, 1 / l);
}

// ---------------------------------------------------------------------------
// Fin definitions (fish-space mm)

function medianFin({ name, s0, s1, count, a0, a1, lengths, dorsal, spines, curv, notch, pleat, sag, rect, branchT, segStart, pigment }) {
  const rays = [];
  const normal = [0, 0, 1];
  for (let k = 0; k < count; k++) {
    const f = k / (count - 1);
    const s = s0 + (s1 - s0) * f;
    const y = dorsal ? topY(s) - 0.14 : botY(s) + 0.14;
    const a = (a0 + (a1 - a0) * f) * DEG;
    const dir = nrm([Math.cos(a), Math.sin(a), 0]);
    rays.push({ base: [s, y, 0], dir, len: lengths[k], kind: k < spines ? 'spine' : 'soft', curv, bend: inPlaneBend(dir, normal) });
  }
  return { name, rays, normal, notch, pleat, sag, rect, branchT, segStart, pigment, cup: 0, wave: 0.0 };
}

function caudalFin(rect) {
  const rays = [];
  const normal = [0, 0, 1];
  const q = section(40.9);
  // dorsal procurrent rays (short, unbranched), principal rays, ventral procurrent rays
  const proc = [[38.9, 1.0, 13], [39.5, 1.9, 16], [40.1, 3.0, 18.5]];
  for (const [s, len, ang] of proc) {
    const dir = nrm([Math.cos(ang * DEG), Math.sin(ang * DEG), 0]);
    rays.push({ base: [s, topY(s) - 0.12, 0], dir, len, kind: 'spine', curv: 0, bend: [0, 0, 0] });
  }
  const NP = 17;
  for (let k = 0; k < NP; k++) {
    const f = k / (NP - 1);
    const u = 2 * f - 1; // -1 dorsal … +1 ventral
    const s = 40.85 - 0.3 * Math.abs(u);
    const y = q.yc - u * 1.15;
    const ang = -u * 20 * DEG;
    const len = 6.9 + 2.2 * Math.pow(Math.max(0, 1 - u * u), 0.8);
    const dir = nrm([Math.cos(ang), Math.sin(ang), 0]);
    rays.push({ base: [s, y, 0], dir, len, kind: 'soft', curv: 0, bend: [0, 0, 0] });
  }
  for (const [s, len, ang] of proc.slice().reverse()) {
    const dir = nrm([Math.cos(-ang * DEG), Math.sin(-ang * DEG), 0]);
    rays.push({ base: [s, botY(s) + 0.12, 0], dir, len, kind: 'spine', curv: 0, bend: [0, 0, 0] });
  }
  return {
    name: 'Fin_Caudal', rays, normal, notch: 0.035, pleat: 0.035, sag: 0.025, rect, branchT: 0.5, segStart: 0.12, cup: 0, wave: 0.16,
    pigment: (r, n, Lr, len, t, dRay, fAcross) => {
      let mel = 0;
      const upper = 1 - fAcross;
      for (let j = 0; j < 12; j++) {
        const Lj = 0.8 + j * 0.78 + r * 0.015;
        if (Lj > len * 0.9) break;
        mel = Math.max(mel, Math.exp(-(((Lr - Lj) / 0.17) ** 2)) * Math.exp(-((dRay / 0.085) ** 2)));
      }
      mel *= (0.55 + 0.45 * upper) * smoothstep(0.97, 0.75, t);
      // dark spot at the caudal base
      mel = Math.max(mel, 0.55 * smoothstep(0.16, 0.04, t) * smoothstep(0.62, 0.3, Math.abs(fAcross - 0.45) * 2));
      return { mel: mel * 0.85, xan: 0.18 * smoothstep(0.6, 0.1, t), irid: 0.08 };
    },
  };
}

function pectoralFin(side, rect) {
  const rays = [];
  const NR = 20;
  const Xf = nrm([1, 0, 0.4 * side]);
  const Yf = nrm(sub([0, 1, 0], mul(Xf, dot([0, 1, 0], Xf))));
  let normal = nrm(cross(Xf, Yf));
  if (normal[2] * side < 0) normal = mul(normal, -1);
  for (let k = 0; k < NR; k++) {
    const f = k / (NR - 1);
    const s = 12.0 + 0.45 * f + 0.15 * f * f;
    const y = 3.5 - 2.3 * f;
    const sp = surfaceAt(s, y).p;
    const base = [s, y, side * (sp[2] - 0.12)];
    const psi = (40 - f * 92) * DEG;
    const dir = nrm(add(mul(Xf, Math.cos(psi)), mul(Yf, Math.sin(psi))));
    const len = 4.6 + 2.8 * Math.pow(Math.max(0, 1 - ((f - 0.4) / 0.62) ** 2), 0.75);
    rays.push({ base, dir, len, kind: 'soft', curv: 0.05, bend: inPlaneBend(dir, normal) });
  }
  return {
    name: side > 0 ? 'Fin_Pectoral_L' : 'Fin_Pectoral_R', rays, normal, notch: 0.03, pleat: 0.06, sag: 0.03, rect, branchT: 0.45, segStart: 0.15, cup: 0.22, wave: 0.05,
    pigment: (r, n, Lr, len, t, dRay, fAcross) => {
      let mel = 0;
      for (let j = 0; j < 3; j++) {
        const Lj = 0.7 + j * 0.75 + r * 0.03;
        mel = Math.max(mel, Math.exp(-(((Lr - Lj) / 0.12) ** 2)) * Math.exp(-((dRay / 0.06) ** 2)));
      }
      mel *= 0.4 * smoothstep(0.7, 0.2, fAcross);
      return { mel, xan: 0.16 * smoothstep(0.5, 0.0, t), irid: 0.14 * smoothstep(0.25, 0.0, t) };
    },
  };
}

function pelvicDisc(rect) {
  const rays = [];
  const N = 12;
  for (let k = 0; k < N; k++) {
    const f = k / (N - 1);
    const u = 2 * f - 1; // +1 … -1 across (left … right)
    const spine = k === 0 || k === N - 1;
    const s = 11.75 + 0.18 * Math.abs(u);
    const z = -u * 0.9;
    const y = botY(s) + 0.12;
    const th = -u * (spine ? 46 : 38) * DEG;
    const dir = nrm([Math.cos(th), -(0.16 + 0.16 * Math.abs(u)), Math.sin(th)]);
    const len = spine ? 1.5 : 4.4 + 1.6 * (1 - Math.abs(u));
    rays.push({ base: [s, y, z], dir, len, kind: spine ? 'spine' : 'soft', curv: 0.04, bend: [0, 0, 0] });
  }
  const normal = [0, -1, 0];
  for (const r of rays) r.bend = inPlaneBend(r.dir, normal);
  return {
    name: 'Fin_Pelvic', rays, normal, notch: 0.04, pleat: 0.03, sag: 0.03, rect, branchT: 0.55, segStart: 0.2, cup: -0.18, wave: 0,
    pigment: (r, n, Lr, len, t) => ({ mel: 0, xan: 0.1, irid: 0.42 * smoothstep(1.0, 0.2, t) }),
  };
}

export function finDefinitions() {
  const R = (x, y, w, h) => ({ x, y, w, h });
  const D1 = medianFin({
    name: 'Fin_Dorsal1', s0: 13.6, s1: 17.6, count: 8, a0: 66, a1: 38, dorsal: true, spines: 8, curv: 0.09, notch: 0.3, pleat: 0.04, sag: 0.02,
    lengths: [3.9, 4.8, 5.1, 4.9, 4.4, 3.7, 2.9, 2.0], rect: R(1024, 1024, 512, 512), branchT: 2, segStart: 2,
    pigment: (r, n, Lr, len, t, dRay) => {
      let mel = 0;
      for (let j = 0; j < 9; j++) {
        const Lj = 0.55 + j * 0.6 + r * 0.08;
        if (Lj > len * 0.86) break;
        mel = Math.max(mel, Math.exp(-(((Lr - Lj) / 0.14) ** 2)) * Math.exp(-((dRay / 0.1) ** 2)));
      }
      return { mel: 0.85 * mel + 0.05, xan: 0.25 * smoothstep(0.5, 0.0, t), irid: 0.05 };
    },
  });
  const D2 = medianFin({
    name: 'Fin_Dorsal2', s0: 19.2, s1: 33.0, count: 14, a0: 60, a1: 27, dorsal: true, spines: 1, curv: 0.03, notch: 0.07, pleat: 0.05, sag: 0.025,
    lengths: [2.9, 3.6, 4.0, 4.2, 4.3, 4.35, 4.4, 4.4, 4.45, 4.5, 4.55, 4.5, 4.35, 3.9], rect: R(0, 1024, 1024, 512), branchT: 0.55, segStart: 0.18,
    pigment: (r, n, Lr, len, t, dRay) => {
      let mel = 0;
      for (let j = 0; j < 9; j++) {
        const Lj = 0.42 + j * 0.52 + r * 0.05;
        if (Lj > len * 0.88) break;
        mel = Math.max(mel, Math.exp(-(((Lr - Lj) / 0.13) ** 2)) * Math.exp(-((dRay / 0.08) ** 2)));
      }
      return { mel: 0.78 * mel + 0.04, xan: 0.22 * smoothstep(0.6, 0.0, t), irid: 0.05 };
    },
  });
  const AN = medianFin({
    name: 'Fin_Anal', s0: 23.7, s1: 33.2, count: 12, a0: -58, a1: -27, dorsal: false, spines: 1, curv: 0.03, notch: 0.07, pleat: 0.05, sag: 0.025,
    lengths: [2.1, 2.9, 3.3, 3.5, 3.6, 3.65, 3.7, 3.7, 3.75, 3.8, 3.75, 3.5], rect: R(0, 1536, 1024, 512), branchT: 0.55, segStart: 0.18,
