        let cr = mix(0.8, 0.78, rayD), cg = mix(0.78, 0.7, rayD), cb = mix(0.72, 0.52, rayD);
        cr *= mix(1, 1.0, xan); cg *= mix(1, 0.86, xan); cb *= mix(1, 0.5, xan);
