        cr *= Math.exp(-mel * 2.4); cg *= Math.exp(-mel * 2.8); cb *= Math.exp(-mel * 3.1);
        const o = (py * S + px) * 4;
        const opacity = clamp(0.2 + 0.5 * rayD + 0.75 * mel + 0.3 * irid);
        color[o] = srgb(cr); color[o + 1] = srgb(cg); color[o + 2] = srgb(cb); color[o + 3] = Math.round(cov * opacity * 255);
