      let nx = -gx, ny = -gy, nz = 1;
      const l = Math.hypot(nx, ny, nz);
      normal[i * 3] = Math.round((nx / l * 0.5 + 0.5) * 255);
      normal[i * 3 + 1] = Math.round((ny / l * 0.5 + 0.5) * 255);
      normal[i * 3 + 2] = Math.round((nz / l * 0.5 + 0.5) * 255);
    }
  return { size: S, color, data, normal };
}

