const body = buildBody({ NS: fast ? 200 : 400, NV: fast ? 96 : 192, texW: fast ? 1024 : 2048, texH: fast ? 512 : 1024, log });
const BT = body.textures;
const tAlb = gb.addTexture(image(gb, 'body_basecolor', BT.width, BT.height, 3, BT.albedo, 'jpeg', 93), sBody, 'body_basecolor');
const tNrm = gb.addTexture(image(gb, 'body_normal', BT.width, BT.height, 3, BT.normal, 'png'), sBody, 'body_normal');
const tOrm = gb.addTexture(image(gb, 'body_orm', BT.width, BT.height, 3, BT.orm, 'png'), sBody, 'body_occlusion_roughness');
const tVol = gb.addTexture(image(gb, 'body_transmission_thickness', BT.width, BT.height, 3, BT.volume, 'png'), sBody, 'body_transmission_thickness');
const tPig = gb.addTexture(image(gb, 'body_pigment', BT.width, BT.height, 3, BT.pigment, 'png'), sBody, 'body_pigment_mel_irid_xan');

