  name: 'Mahaze_Juvenile',
  children: nodes,
  extras: {
    species: 'Acanthogobius flavimanus (Temminck & Schlegel, 1845)',
    commonName: 'マハゼ (yellowfin goby), juvenile',
    totalLength_mm: TL,
    standardLength_mm: SL,
    units: 'metres (+Y dorsal, +Z anterior)',
  },
});
gb.addScene('Mahaze', [rootNode]);
