+}
+`;
+
+export function createBodyMaterial({ textures, profileTexture, frame, vertebrae, shared }) {
+  const uniforms = {
+    ...shared,
+    uAlbedo: { value: textures.albedo },
+    uNormalMap: { value: textures.normal },
+    uORM: { value: textures.orm },
+    uPigment: { value: textures.pigment },
