// ---------------------------------------------------------------------------- camera presets
const PRESETS = {
  whole: { target: [0, 0.0005, 0.0], pos: [0.082, 0.024, 0.036] },
  head: { target: [0.0005, 0.0012, 0.0185], pos: [0.022, 0.011, 0.034] },
  tail: { target: [0, 0.0003, -0.017], pos: [0.028, 0.006, -0.008] },
  below: { target: [0, -0.001, 0.004], pos: [0.045, -0.03, 0.03] },
