function updateFloorShadow() {
  if (!fish.profile) return;
  const P = fish.profile, F = fish.frame;
  const arr = floor.material.uniforms.uShadow.value;
  shadowS.forEach((s, i) => {
    const k = Math.min(P.n - 1, Math.round((Math.min(s, F.SEND) / F.SEND) * (P.n - 1)));
