    const e = camTween.t < 0.5 ? 4 * camTween.t ** 3 : 1 - (-2 * camTween.t + 2) ** 3 / 2;
    controls.target.lerpVectors(camTween.from.target, camTween.to.target, e);
    camera.position.lerpVectors(camTween.from.pos, camTween.to.pos, e);
