        vec3 p = vWorldPos;
        vec2 mm = p.xz * 1000.0;
        float dist = length(cameraPosition - p);
        float fw = length(fwidth(mm));
        // grain layers (fine sand ~0.25 mm, coarse ~0.7 mm)
        vec2 o1, o2;
        vec3 g1 = grains(mm / 0.28, o1);
        vec3 g2 = grains(mm / 0.75 + 17.0, o2);
        float detail1 = 1.0 - smoothstep(0.08, 0.3, fw * 0.5 / 0.28);
        float detail2 = 1.0 - smoothstep(0.08, 0.3, fw * 0.5 / 0.75);
        vec3 sandA = vec3(0.42, 0.37, 0.29), sandB = vec3(0.56, 0.53, 0.47), dark = vec3(0.1, 0.1, 0.1), quartz = vec3(0.75, 0.74, 0.7);
        vec3 c1 = mix(sandA, sandB, g1.y);
        c1 = g1.z > 0.9 ? dark : (g1.z > 0.78 ? quartz : c1);
        vec3 c2 = mix(sandA * 0.85, sandB, g2.y);
        c2 = g2.z > 0.88 ? dark * 1.3 : (g2.z > 0.8 ? quartz : c2);
        float edge1 = smoothstep(0.55, 0.95, g1.x);
        float edge2 = smoothstep(0.6, 0.98, g2.x);
        vec3 avg = mix(sandA, sandB, 0.5) * 0.92;
        vec3 alb = mix(avg, mix(c1, c1 * 0.55, edge1), detail1);
        alb = mix(alb, mix(alb, c2 * (1.0 - 0.45 * edge2), 0.55), detail2);
        // ripples
        float rip = sin(mm.x * 0.35 + sin(mm.y * 0.08) * 2.0) * 0.5 + 0.5;
        vec3 N = normalize(vec3(cos(mm.x * 0.35 + sin(mm.y * 0.08) * 2.0) * 0.18, 1.0, 0.0));
        // grain bump normals (each grain is a small dome)
        N = normalize(N + vec3(-o1.x, 0.0, -o1.y) * 0.9 * detail1 * (1.0 - edge1) + vec3(-o2.x, 0.0, -o2.y) * 0.6 * detail2 * (1.0 - edge2));
        vec3 L = normalize(uLightDir);
        float caus = mix(1.0, caustics(p.xz * 180.0 - L.xz / max(L.y, 0.2) * p.y * 180.0), uCausticAmt * 2.2);
        float occ = softShadow(p, L);
        vec3 shadowTint = mix(vec3(1.0), vec3(0.42, 0.34, 0.25), occ);   // translucent body → warm, soft shadow
        vec3 Lc = uLightColor * caus * shadowTint * mix(1.0, 0.9, rip);
        float ndl = max(dot(N, L), 0.0);
