        float fw = length(fwidth(mm));
        // three grain populations: silt-fine, fine sand (~0.2 mm), medium sand (~0.45 mm)
        vec2 o1, o2, o3;
        vec3 g1 = grains(mm / 0.2, o1);
        vec3 g2 = grains(mm / 0.45 + 17.0, o2);
        vec3 g3 = grains(mm / 0.09 + 5.0, o3);
        float detail1 = 1.0 - smoothstep(0.1, 0.35, fw * 0.5 / 0.2);
        float detail2 = 1.0 - smoothstep(0.1, 0.35, fw * 0.5 / 0.45);
        float detail3 = 1.0 - smoothstep(0.1, 0.35, fw * 0.5 / 0.09);
        vec3 sandA = vec3(0.34, 0.3, 0.24), sandB = vec3(0.5, 0.47, 0.41), dark = vec3(0.07, 0.07, 0.07), quartz = vec3(0.66, 0.65, 0.62), shell = vec3(0.62, 0.55, 0.48);
        // large-scale mottling (organic film, patches of darker grains)
        float mott = 0.5 + 0.5 * sin(mm.x * 0.031 + sin(mm.y * 0.023) * 2.3) * sin(mm.y * 0.027 - mm.x * 0.011);
        vec3 avg = mix(sandA, sandB, 0.45 + 0.2 * mott) * 0.95;
        vec3 c1 = mix(sandA, sandB, g1.y);
        c1 = g1.z > 0.93 ? dark : (g1.z > 0.84 ? quartz : (g1.z > 0.8 ? shell : c1));
        vec3 c2 = mix(sandA * 0.9, sandB, g2.y);
        c2 = g2.z > 0.9 ? dark * 1.4 : (g2.z > 0.82 ? quartz : c2);
        float edge1 = smoothstep(0.6, 0.98, g1.x);
        float edge2 = smoothstep(0.65, 1.0, g2.x);
        vec3 alb = mix(avg, mix(c1, c1 * 0.72, edge1), detail1 * 0.85);
        alb = mix(alb, mix(alb, c2 * (1.0 - 0.25 * edge2), 0.5), detail2);
        alb *= mix(1.0, 0.85 + 0.3 * g3.y, detail3 * 0.6);
        // long, low ripples
        float ph = mm.x * 0.085 + sin(mm.y * 0.021) * 2.4 + sin(mm.y * 0.05 + mm.x * 0.01) * 0.6;
        vec3 N = normalize(vec3(cos(ph) * 0.07, 1.0, sin(mm.y * 0.021) * 0.02));
        // grain domes
        N = normalize(N + vec3(-o1.x, 0.0, -o1.y) * 0.7 * detail1 * (1.0 - edge1) + vec3(-o2.x, 0.0, -o2.y) * 0.5 * detail2 * (1.0 - edge2));
        vec3 L = normalize(uLightDir);
