        float occ = softShadow(p, L);
        vec3 shadowTint = mix(vec3(1.0), vec3(0.45, 0.37, 0.28), occ);   // translucent body -> warm, soft shadow
        vec3 Lc = uLightColor * caus * shadowTint;
