function sortFins() {
  const list = fish.fins.map((f) => ({ f, d: _v.copy(f.center).applyMatrix4(f.mesh.matrixWorld).distanceToSquared(camera.position) }));
  list.sort((a, b) => b.d - a.d);
  list.forEach(({ f }, i) => {
    f.mesh.renderOrder = 100 + i * 2;
    f.scatter.renderOrder = 101 + i * 2;
  });
}

