137	/** Normalised height inside the section (-1 ventral … +1 dorsal). */
138	export function normHeight(s, y) {
139	  const q = section(clamp(s, 0.01, S_END - 0.01));
140	  const dy = y - q.yc;
141	  return dy / Math.max(dy > 0 ? q.t : q.b, 1e-3);
142	}
143	
144	// ---------------------------------------------------------------------------
145	// Sculpt features (smooth CSG on top of the loft)
146	
147	const smin = (a, b, k) => {
148	  const h = clamp(0.5 + (0.5 * (b - a)) / k, 0, 1);
149	  return b + (a - b) * h - k * h * (1 - h);
150	};
151	const smax = (a, b, k) => -smin(-a, -b, k);
152	
153	const norm3 = (v) => { const l = Math.hypot(v[0], v[1], v[2]); return [v[0] / l, v[1] / l, v[2] / l]; };
154	
155	/** Base-surface point on the +z side at (s, y) and its outward normal. */
156	export function surfaceAt(s, y) {
157	  const q = section(s);
158	  const dy = y - q.yc;
159	  const up = dy > 0;
160	  const h = up ? q.t : q.b;
161	  const n = up ? q.nT : q.nB;
162	  const a = clamp(Math.abs(dy) / h, 0, 1);
163	  const z = q.w * Math.pow(Math.max(0, 1 - Math.pow(a, n)), 1 / n);
164	  const e = 0.005;
165	  const g = [
166	    baseDist(s + e, y, z) - baseDist(s - e, y, z),
167	    baseDist(s, y + e, z) - baseDist(s, y - e, z),
168	    baseDist(s, y, z + e) - baseDist(s, y, z - e),
169	  ];
170	  return { p: [s, y, z], n: norm3(g) };
171	}
172	
173	// Eye (left side, +z). Right eye mirrors z.
174	export const EYE = {
175	  center: [5.3, 4.2, 1.45],
176	  axis: norm3([-0.2, 0.72, 0.66]),
177	  radius: 1.25,
178	  skin: 0.1,
179	  aperture: 57 * (Math.PI / 180),
180	};
181	
182	// Mouth line (s, y) on the lateral surface; lips follow it.
183	export const MOUTH = [[0.02, 1.98], [0.35, 1.9], [0.9, 1.75], [1.6, 1.58], [2.5, 1.42], [3.4, 1.3], [4.2, 1.22], [4.8, 1.18]];
184	// Opercular margin (s, y)
185	export const OPERCLE = [[10.0, 4.75], [10.7, 4.2], [11.25, 3.4], [11.45, 2.5], [11.3, 1.6], [10.8, 0.85], [10.0, 0.35]];
186	// Preopercular groove (s, y)
187	export const PREOPERCLE = [[7.2, 4.0], [7.9, 3.3], [8.25, 2.5], [8.0, 1.7], [7.2, 1.05], [6.2, 0.65]];
188	
189	function onSurface(poly, inset = 0, lift = 0, dy = 0) {
190	  return poly.map(([s, y]) => {
191	    const { p, n } = surfaceAt(s, y + dy);
192	    return [p[0] - n[0] * inset, p[1] - n[1] * inset + lift, p[2] - n[2] * inset];
193	  });
194	}
195	
196	function capsuleChain(pts, radii) {
197	  const segs = [];
198	  for (let i = 0; i < pts.length - 1; i++) segs.push([pts[i], pts[i + 1], radii[i], radii[i + 1]]);
199	  return segs;
200	}
201	
202	function capsuleChainDist(p, segs) {
203	  let best = 1e9;
204	  for (const [a, b, ra, rb] of segs) {
205	    const ab = [b[0] - a[0], b[1] - a[1], b[2] - a[2]];
206	    const ap = [p[0] - a[0], p[1] - a[1], p[2] - a[2]];
207	    const L2 = ab[0] * ab[0] + ab[1] * ab[1] + ab[2] * ab[2];
208	    const t = clamp((ap[0] * ab[0] + ap[1] * ab[1] + ap[2] * ab[2]) / L2, 0, 1);
209	    const d = Math.hypot(ap[0] - ab[0] * t, ap[1] - ab[1] * t, ap[2] - ab[2] * t) - (ra + (rb - ra) * t);
210	    if (d < best) best = d;
211	  }
212	  return best;
213	}
214	
215	const mirrorZ = (segs) => segs.map(([a, b, ra, rb]) => [[a[0], a[1], -a[2]], [b[0], b[1], -b[2]], ra, rb]);
216	
217	function ellipsoidDist(p, c, r) {
218	  const k0 = Math.hypot((p[0] - c[0]) / r[0], (p[1] - c[1]) / r[1], (p[2] - c[2]) / r[2]);
219	  const k1 = Math.hypot((p[0] - c[0]) / (r[0] * r[0]), (p[1] - c[1]) / (r[1] * r[1]), (p[2] - c[2]) / (r[2] * r[2]));
220	  return k1 > 0 ? (k0 * (k0 - 1)) / k1 : -Math.min(r[0], r[1], r[2]);
221	}
222	
223	const sphereDist = (p, c, r) => Math.hypot(p[0] - c[0], p[1] - c[1], p[2] - c[2]) - r;
224	
225	function buildFeatures() {
226	  const upperLip = onSurface(MOUTH.map(([s, y]) => [s, y]), 0.14, 0.12);
227	  const lowerLip = onSurface(MOUTH.map(([s, y]) => [s, y]), 0.15, -0.14);
228	  const mouthCrease = onSurface(MOUTH, 0.0, 0.0);
229	  upperLip[0][2] = 0; lowerLip[0][2] = 0; mouthCrease[0][2] = 0;
230	  const n = MOUTH.length;
231	  const ru = MOUTH.map((_, i) => (i === 0 ? 0.12 : i === 1 ? 0.16 : 0.19 - 0.08 * (i / (n - 1))));
232	  const rl = MOUTH.map((_, i) => 0.16 - 0.08 * (i / (n - 1)));
233	  const rc = MOUTH.map((_, i) => 0.06 - 0.02 * (i / (n - 1)));
234	  const lipsU = capsuleChain(upperLip, ru);
235	  const lipsL = capsuleChain(lowerLip, rl);
236	  const crease = capsuleChain(mouthCrease, rc);
237	  const operc = capsuleChain(onSurface(OPERCLE, -0.01), OPERCLE.map((_, i) => (i === OPERCLE.length - 1 ? 0.03 : 0.05)));
238	
239	  const pecSurf = surfaceAt(12.35, 2.35);
240	  const pecLobe = [pecSurf.p[0], pecSurf.p[1], pecSurf.p[2] - 0.28];
241	
242	  const nosA = surfaceAt(1.35, 3.25);
243	  const nosB = surfaceAt(2.55, 3.95);
244	
245	  const E = EYE;
246	  const Rs = E.radius + E.skin;
247	  const cutOff = 1.3;
248	  const rho = Math.sqrt(Rs * Rs + cutOff * cutOff - 2 * Rs * cutOff * Math.cos(E.aperture));
249	  const eyeL = { c: E.center, cut: [E.center[0] + E.axis[0] * cutOff, E.center[1] + E.axis[1] * cutOff, E.center[2] + E.axis[2] * cutOff] };
250	  const eyeR = { c: [eyeL.c[0], eyeL.c[1], -eyeL.c[2]], cut: [eyeL.cut[0], eyeL.cut[1], -eyeL.cut[2]] };
251	
252	  return {
253	    lipsU, lipsUR: mirrorZ(lipsU), lipsL, lipsLR: mirrorZ(lipsL),
254	    crease, creaseR: mirrorZ(crease), operc, opercR: mirrorZ(operc),
255	    pecLobe, nosA: nosA.p, nosAn: nosA.n, nosB: nosB.p,
256	    eyes: [eyeL, eyeR], Rs, rho,
257	    papilla: [22.9, botY(22.9) + 0.02, 0],
258	    anus: [22.45, botY(22.45) - 0.03, 0],
259	    pelvicBase: [12.0, botY(12.0) + 0.08, 0],
260	    interorb: [5.4, topY(5.4) + 0.28, 0],
261	  };
262	}
263	
264	export const FEAT = buildFeatures();
265	
266	/** Sculpted signed distance field (mm). Negative inside the fish. */
267	export function field(s, y, z) {
268	  const F = FEAT;
269	  const p = [s, y, z];
270	  const az = Math.abs(z);
271	  const pm = [s, y, az]; // mirrored to the +z side for symmetric features
272	  let d = baseDist(s, y, z);
273	  // eye bulges
274	  for (const e of F.eyes) d = smin(d, sphereDist(p, e.c, F.Rs), 0.5);
275	  // lips
276	  if (s < 6.5 && y < 3.2) {
277	    d = smin(d, capsuleChainDist(p, z >= 0 ? F.lipsU : F.lipsUR), 0.18);
278	  }
279	  // pectoral fin base (fleshy lobe)
280	  if (s > 10.5 && s < 14.5) d = smin(d, ellipsoidDist(pm, F.pecLobe, [0.75, 1.55, 0.45]), 0.3);
281	  // pelvic disc base
282	  if (s > 10 && s < 14) d = smin(d, ellipsoidDist(p, F.pelvicBase, [1.1, 0.22, 0.9]), 0.25);
283	  // urogenital papilla
284	  if (s > 21.5 && s < 24.5) d = smin(d, sphereDist(p, F.papilla, 0.26), 0.15);
285	  // anterior nostril tube
286	  if (s < 3) d = smin(d, sphereDist(pm, [F.nosA[0] + F.nosAn[0] * 0.02, F.nosA[1] + F.nosAn[1] * 0.02, F.nosA[2] + F.nosAn[2] * 0.02], 0.11), 0.07);
287	
288	  // --- subtractions
289	  for (const e of F.eyes) d = smax(d, -sphereDist(p, e.cut, F.rho), 0.14);
290	  if (s < 6.5 && y < 3.0) d = smax(d, -capsuleChainDist(p, z >= 0 ? F.crease : F.creaseR), 0.05);
291	  if (s > 9 && s < 12.5) d = smax(d, -capsuleChainDist(p, z >= 0 ? F.operc : F.opercR), 0.05);
292	  if (s > 3 && s < 8) d = smax(d, -ellipsoidDist(p, F.interorb, [1.7, 0.42, 0.55]), 0.3);
293	  if (s > 21.5 && s < 23.5) d = smax(d, -sphereDist(p, F.anus, 0.09), 0.05);
294	  if (s < 4) d = smax(d, -sphereDist(pm, F.nosB, 0.1), 0.06);
295	  return d;
296	}
297	
298	export function fieldGrad(s, y, z, e = 0.004) {
299	  const g = [
300	    field(s + e, y, z) - field(s - e, y, z),
301	    field(s, y + e, z) - field(s, y - e, z),
302	    field(s, y, z + e) - field(s, y, z - e),
303	  ];
304	  return norm3(g);
305	}
306	
307	/** Origin of the projection ray for a loft section. */
308	export function rayOrigin(s) {
309	  const sc = clamp(s, 2.6, 40.2);
310	  const q = section(sc);
311	  return [sc, q.yc, 0];
312	}
313	
314	/** Moves a base-loft point onto the sculpted surface along the ray from the section origin. */
315	export function project(p0) {
316	  const o = rayOrigin(p0[0]);
317	  let dir = [p0[0] - o[0], p0[1] - o[1], p0[2] - o[2]];
318	  const L = Math.hypot(dir[0], dir[1], dir[2]);
319	  if (L < 1e-6) return p0.slice();
320	  dir = [dir[0] / L, dir[1] / L, dir[2] / L];
321	  const at = (t) => field(o[0] + dir[0] * t, o[1] + dir[1] * t, o[2] + dir[2] * t);
322	  let t0 = Math.max(0.02, L - 1.2);
323	  while (t0 > 0.02 && at(t0) > 0) t0 = Math.max(0.02, t0 - 0.5);
324	  const step = 0.035;
325	  let t1 = t0;
326	  let found = false;
327	  for (let i = 0; i < 140; i++) {
328	    const t = t0 + step * (i + 1);
329	    if (at(t) > 0) { t1 = t; found = true; break; }

