1	// Body mesh + baked surface textures for the juvenile goby.
2	import {
3	  S_END, SL, VERT_START, VERT_COUNT, EYE, MOUTH, OPERCLE, PREOPERCLE,
4	  section, basePoint, project, fieldGrad, field, throughDist, toObject, dirToObject,
5	} from './anatomy.mjs';
6	import { perlin3, fbm3, ridged3, hash01, hash3i, clamp, mix, smoothstep } from '../lib/noise.mjs';
7	
8	const TAU = Math.PI * 2;
9	
10	function distributeSections(NS) {
11	  // density of loft sections along the axis (denser at the snout/head and caudal insertion)
12	  const M = 20000;
13	  const cdf = new Float64Array(M + 1);
14	  for (let i = 1; i <= M; i++) {
15	    const s = (i / M) * S_END;
16	    const d = 1.0 + 2.2 * Math.exp(-s / 1.1) + 1.15 * smoothstep(13.5, 8.5, s) + 0.4 * smoothstep(39.5, 42.2, s);
17	    cdf[i] = cdf[i - 1] + d;
18	  }
19	  const out = new Float64Array(NS);
20	  let k = 0;
21	  for (let i = 0; i < NS; i++) {
22	    const target = (i / (NS - 1)) * cdf[M];
23	    while (k < M && cdf[k + 1] < target) k++;
24	    const f = (target - cdf[k]) / Math.max(cdf[k + 1] - cdf[k], 1e-12);
25	    out[i] = ((k + f) / M) * S_END;
26	  }
27	  out[0] = 0;
28	  out[NS - 1] = S_END;
29	  return out;
30	}
31	
32	const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
33	const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
34	const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
