37	/** Inverse of basePoint(): loft parameter phi for a fish-space point. */
38	export function invPhi(s, y, z) {
39	  const q = section(clamp(s, 0.01, S_END - 0.01));
40	  const dy = y - q.yc;
41	  const up = dy > 0;
42	  const n = up ? q.nT : q.nB;
43	  const h = Math.max(up ? q.t : q.b, 1e-4);
44	  const a = Math.sign(z) * Math.pow(Math.abs(z) / Math.max(q.w, 1e-4), n / 2);
45	  const c = -Math.sign(dy) * Math.pow(Math.abs(dy) / h, n / 2);
