        const nf = [-v.n[2], v.n[1], v.n[0]];
        const depth = 0.07;
        const p = sub(v.fish, mul(nf, depth));
        const u = r / ROWS;
        row.push(out.vert(p, [...lining.map((c) => c * (0.8 + 0.2 * hash01(r, k, 3, 4))), 1], [k / (J - 1), u], 'flapLining', 1, 0));
      }
      lin.push(row);
    }
    const faceInward = (c) => {
      // lining looks toward the body interior (opposite the skin normal)
      const q = section(c[0]);
      return [0, q.yc - c[1], -c[2]];
    };
    out.grid(lin, faceInward);
    // 2) free edge strip joining the outer skin (flap copy) to the lining
    const edgeRows = [E.flap.map((g) => out.vert(V[g].fish, [...edgeC, 1], [0, 0], 'flapLining', 1, 0)), lin[0]];
    out.grid(edgeRows, (c) => [1, 0, 0]);
    // 3) chamber wall: starts at the body-side cut and runs forward under the flap, 0.55 mm deep
    const wallRows = [];
    for (let r = 0; r <= ROWS; r++) {
      const row = [];
      for (let k = 0; k < J; k++) {
        const v = V[r === 0 ? E.body[k] : gidAt(im - r, js[k])];
        const nf = [-v.n[2], v.n[1], v.n[0]];
        const d = r === 0 ? 0 : 0.18 + 0.4 * smoothstep(0, 6, r);
        const p = sub(v.fish, mul(nf, d));
        if (r === 0) p[0] += 0.0;
        const endFade = Math.min(k, J - 1 - k) / 3;
        row.push(out.vert(p, [...wall.map((c) => c * (0.7 + 0.3 * clamp(endFade))), 1], [k / (J - 1), r / ROWS], 'gillWall', 0, 0));
      }
      wallRows.push(row);
    }
    out.grid(wallRows, (c) => {
      const q = section(c[0]);
      return [0.3, 0, Math.sign(c[2]) * 1].map((x, i) => (i === 1 ? (q.yc - c[1]) * 0 : x));
    });
    // 4) four gill arches: ribbons standing on the wall, parallel to the margin, filament texture via `gill`
    for (let a = 0; a < 4; a++) {
      const r = 4 + a * 5;
      const H = 0.34 - a * 0.03;
      const base = [], top = [];
      for (let k = 1; k < J - 1; k++) {
        const w = V[wallRows[r][k]] ? null : null;
        const pw = out.v[wallRows[r][k]].fish;
        const v = V[gidAt(im - r, js[k])];
        const nf = [-v.n[2], v.n[1], v.n[0]];
        const lat = Math.sin((Math.PI * k) / (J - 1));
        base.push(out.vert(pw, [0.5, 0.05, 0.05, 1], [k / (J - 1), 0], 'gillArch', 0, 1));
        top.push(out.vert(add(pw, mul(nf, H * (0.4 + 0.6 * lat))), [0.85, 0.16, 0.14, 1], [k / (J - 1), 1], 'gillArch', 0, 1));
      }
      out.grid([base, top], (c) => [1, 0, 0]);
      // back face of the ribbon too (arches are seen from both sides when the cover swings)
      out.grid([top, base], (c) => [-1, 0, 0]);
    }
  }
  return out.finish('Gill_Chamber');
}

