180	loadModel(MODEL_URL).catch((err) => fail(`モデルを読み込めませんでした: ${err && err.message ? err.message : err}`));
181	
182	async function onLoaded(gltf) {
183	  const parser = gltf.parser;
184	  const root = gltf.scene;
185	  const meshes = [];
186	  root.traverse((o) => { if (o.isMesh) meshes.push(o); });
187	  for (const m of meshes) {
188	    m.layers.set(LAYER_FISH);
189	    fish.originals.set(m, m.material);
190	    const x = m.material.userData.mahaze || {};
191	    if (x.role === 'body') fish.body = m;
192	    else if (x.role === 'eye') fish.eyes.push(m);
193	    else if (x.role === 'fin') fish.fins.push({ mesh: m });
194	  }
195	  if (!fish.body) throw new Error('Body mesh not found in glTF');
196	
197	  // body
198	  const bx = fish.body.material.userData.mahaze;
199	  const pigment = await parser.getDependency('texture', bx.pigmentTexture);
200	  pigment.colorSpace = THREE.NoColorSpace;
201	  fish.profile = bx.profile;
202	  fish.frame = bx.fishFrame;
203	  const orig = fish.body.material;
204	  const bodyMat = createBodyMaterial({
205	    textures: { albedo: orig.map, normal: orig.normalMap, orm: orig.roughnessMap || orig.aoMap, pigment },
206	    profileTexture: createProfileTexture(bx.profile),
207	    frame: bx.fishFrame,
208	    vertebrae: bx.vertebrae,
209	    shared,
210	  });
211	  fish.body.userData.custom = bodyMat;
212	  fish.body.onBeforeRender = () => {
213	    if (fish.body.material === bodyMat) bodyMat.uniforms.uInvModel.value.copy(fish.body.matrixWorld).invert();
214	  };
215	
216	  // eyes
217	  const eyeOrig = fish.eyes[0].material;
218	  const eyeMat = createEyeMaterial({ irisTexture: eyeOrig.map, params: eyeOrig.userData.mahaze, shared });
219	  for (const e of fish.eyes) e.userData.custom = eyeMat;
220	
221	  // fins (two passes each)
222	  const finOrig = fish.fins[0].mesh.material;
