1	// Fins: pleated membrane meshes with individual rays + a shared texture atlas.
2	import { section, topY, botY, surfaceAt, toObject, dirToObject } from './anatomy.mjs';
3	import { perlin3, fbm3, hash01, clamp, mix, smoothstep } from '../lib/noise.mjs';
4	
5	const DEG = Math.PI / 180;
6	const nrm = (a) => { const l = Math.hypot(a[0], a[1], a[2]) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
7	const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
8	const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
9	const mul = (a, k) => [a[0] * k, a[1] * k, a[2] * k];
10	const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
11	const cross = (a, b) => [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]];
12	
13	export const ATLAS = 2048;
14	const INSET = 6;
15	
16	function inPlaneBend(dir, normal) {
17	  // component of the posterior axis (+s) perpendicular to the ray, inside the fin plane
18	  let b = sub([1, 0, 0], mul(dir, dot([1, 0, 0], dir)));
19	  b = sub(b, mul(normal, dot(b, normal)));
20	  const l = Math.hypot(...b);
21	  return l < 1e-5 ? [0, 0, 0] : mul(b, 1 / l);
22	}
23	
24	// ---------------------------------------------------------------------------
25	// Fin definitions (fish-space mm)
26	
27	function medianFin({ name, s0, s1, count, a0, a1, lengths, dorsal, spines, curv, notch, pleat, sag, rect, branchT, segStart, pigment }) {
28	  const rays = [];
29	  const normal = [0, 0, 1];
30	  for (let k = 0; k < count; k++) {
31	    const f = k / (count - 1);
32	    const s = s0 + (s1 - s0) * f;
33	    const y = dorsal ? topY(s) - 0.14 : botY(s) + 0.14;
34	    const a = (a0 + (a1 - a0) * f) * DEG;
35	    const dir = nrm([Math.cos(a), Math.sin(a), 0]);
36	    rays.push({ base: [s, y, 0], dir, len: lengths[k], kind: k < spines ? 'spine' : 'soft', curv, bend: inPlaneBend(dir, normal) });
37	  }
38	  return { name, rays, normal, notch, pleat, sag, rect, branchT, segStart, pigment, cup: 0, wave: 0.0 };
39	}
40	
41	function caudalFin(rect) {
42	  const rays = [];
43	  const normal = [0, 0, 1];
44	  const q = section(40.9);
45	  // dorsal procurrent rays (short, unbranched), principal rays, ventral procurrent rays
46	  const proc = [[38.9, 1.0, 13], [39.5, 1.9, 16], [40.1, 3.0, 18.5]];
47	  for (const [s, len, ang] of proc) {
48	    const dir = nrm([Math.cos(ang * DEG), Math.sin(ang * DEG), 0]);
49	    rays.push({ base: [s, topY(s) - 0.12, 0], dir, len, kind: 'spine', curv: 0, bend: [0, 0, 0] });
50	  }
51	  const NP = 17;
52	  for (let k = 0; k < NP; k++) {
53	    const f = k / (NP - 1);
54	    const u = 2 * f - 1; // -1 dorsal … +1 ventral
55	    const s = 40.85 - 0.3 * Math.abs(u);
56	    const y = q.yc - u * 1.15;
57	    const ang = -u * 20 * DEG;
58	    const len = 6.9 + 2.2 * Math.pow(Math.max(0, 1 - u * u), 0.8);
59	    const dir = nrm([Math.cos(ang), Math.sin(ang), 0]);
60	    rays.push({ base: [s, y, 0], dir, len, kind: 'soft', curv: 0, bend: [0, 0, 0] });
61	  }
62	  for (const [s, len, ang] of proc.slice().reverse()) {
63	    const dir = nrm([Math.cos(-ang * DEG), Math.sin(-ang * DEG), 0]);
64	    rays.push({ base: [s, botY(s) + 0.12, 0], dir, len, kind: 'spine', curv: 0, bend: [0, 0, 0] });
65	  }
66	  return {
67	    name: 'Fin_Caudal', rays, normal, notch: 0.035, pleat: 0.035, sag: 0.025, rect, branchT: 0.5, segStart: 0.12, cup: 0, wave: 0.16,
68	    pigment: (r, n, Lr, len, t, dRay, fAcross) => {
69	      let mel = 0;
70	      const upper = 1 - fAcross;
71	      for (let j = 0; j < 12; j++) {
72	        const Lj = 0.8 + j * 0.8 + r * 0.02 + (hash01(r, j, 2, 502) - 0.5) * 0.28;
73	        if (Lj > len * 0.9) break;
74	        if (hash01(r, j, 1, 501) < 0.3) continue;
75	        const ls = 0.1 + 0.09 * hash01(r, j, 3, 503);
76	        const amp = 0.45 + 0.55 * hash01(r, j, 4, 504);
77	        mel = Math.max(mel, amp * Math.exp(-(((Lr - Lj) / ls) ** 2)) * Math.exp(-((dRay / 0.075) ** 2)));
78	      }
79	      mel *= 0.8 * (0.5 + 0.5 * upper) * smoothstep(0.97, 0.75, t);
80	      // dark spot at the caudal base
81	      mel = Math.max(mel, 0.55 * smoothstep(0.16, 0.04, t) * smoothstep(0.62, 0.3, Math.abs(fAcross - 0.45) * 2));
82	      return { mel: mel * 0.85, xan: 0.18 * smoothstep(0.6, 0.1, t), irid: 0.08 };
83	    },
84	  };
85	}
86	
87	function pectoralFin(side, rect) {
88	  const rays = [];
89	  const NR = 20;
90	  // fin held away from the flank; its lower half flares outward (plane tilted ~30° from vertical)
91	  const Xf = nrm([1, 0, 0.42 * side]);
92	  const up0 = nrm([0, 1, -0.58 * side]);
93	  const Yf = nrm(sub(up0, mul(Xf, dot(up0, Xf))));
94	  let normal = nrm(cross(Xf, Yf));
95	  if (normal[2] * side < 0) normal = mul(normal, -1);
96	  for (let k = 0; k < NR; k++) {
97	    const f = k / (NR - 1);
98	    const s = 12.0 + 0.45 * f + 0.15 * f * f;
99	    const y = 3.5 - 2.3 * f;
100	    const sp = surfaceAt(s, y).p;
101	    const base = [s, y, side * (sp[2] - 0.12)];
102	    const psi = (40 - f * 92) * DEG;
103	    const dir = nrm(add(mul(Xf, Math.cos(psi)), mul(Yf, Math.sin(psi))));
104	    const len = 4.6 + 2.8 * Math.pow(Math.max(0, 1 - ((f - 0.4) / 0.62) ** 2), 0.75);
105	    rays.push({ base, dir, len, kind: 'soft', curv: 0.05, bend: inPlaneBend(dir, normal) });
106	  }
107	  return {
108	    name: side > 0 ? 'Fin_Pectoral_L' : 'Fin_Pectoral_R', rays, normal, notch: 0.03, pleat: 0.06, sag: 0.03, rect, branchT: 0.45, segStart: 0.15, cup: 0.22, wave: 0.05,
109	    pigment: (r, n, Lr, len, t, dRay, fAcross) => {
110	      let mel = 0;
111	      for (let j = 0; j < 3; j++) {
112	        const Lj = 0.7 + j * 0.75 + r * 0.03;
113	        mel = Math.max(mel, Math.exp(-(((Lr - Lj) / 0.12) ** 2)) * Math.exp(-((dRay / 0.06) ** 2)));
114	      }
115	      mel *= 0.4 * smoothstep(0.7, 0.2, fAcross);
116	      return { mel, xan: 0.16 * smoothstep(0.5, 0.0, t), irid: 0.14 * smoothstep(0.25, 0.0, t) };
117	    },
118	  };
119	}
120	
121	function pelvicDisc(rect) {
122	  const rays = [];
123	  const N = 12;
124	  for (let k = 0; k < N; k++) {
125	    const f = k / (N - 1);
126	    const u = 2 * f - 1; // +1 … -1 across (left … right)
127	    const spine = k === 0 || k === N - 1;
128	    const s = 11.75 + 0.18 * Math.abs(u);
129	    const z = -u * 0.9;
130	    const y = botY(s) + 0.12;
131	    const th = -u * (spine ? 46 : 38) * DEG;
132	    const dir = nrm([Math.cos(th), -(0.16 + 0.16 * Math.abs(u)), Math.sin(th)]);
133	    const len = spine ? 1.5 : 4.4 + 1.6 * (1 - Math.abs(u));
134	    rays.push({ base: [s, y, z], dir, len, kind: spine ? 'spine' : 'soft', curv: 0.04, bend: [0, 0, 0] });
135	  }
136	  const normal = [0, -1, 0];
137	  for (const r of rays) r.bend = inPlaneBend(r.dir, normal);
138	  return {
139	    name: 'Fin_Pelvic', rays, normal, notch: 0.04, pleat: 0.03, sag: 0.03, rect, branchT: 0.55, segStart: 0.2, cup: -0.18, wave: 0,
140	    pigment: (r, n, Lr, len, t) => ({ mel: 0, xan: 0.1, irid: 0.42 * smoothstep(1.0, 0.2, t) }),
141	  };
142	}
143	
144	export function finDefinitions() {
145	  const R = (x, y, w, h) => ({ x, y, w, h });
146	  const D1 = medianFin({
147	    name: 'Fin_Dorsal1', s0: 13.6, s1: 17.6, count: 8, a0: 70, a1: 40, dorsal: true, spines: 8, curv: 0.09, notch: 0.3, pleat: 0.04, sag: 0.02,
148	    lengths: [4.3, 5.3, 5.7, 5.5, 4.9, 4.1, 3.2, 2.2], rect: R(1024, 1024, 512, 512), branchT: 2, segStart: 2,
149	    pigment: (r, n, Lr, len, t, dRay) => {
150	      let mel = 0;
151	      for (let j = 0; j < 9; j++) {
152	        const Lj = 0.55 + j * 0.62 + r * 0.08 + (hash01(r, j, 2, 512) - 0.5) * 0.2;
153	        if (Lj > len * 0.86) break;
154	        if (hash01(r, j, 1, 511) < 0.18) continue;
155	        const ls = 0.1 + 0.08 * hash01(r, j, 3, 513);
156	        mel = Math.max(mel, (0.5 + 0.5 * hash01(r, j, 4, 514)) * Math.exp(-(((Lr - Lj) / ls) ** 2)) * Math.exp(-((dRay / 0.1) ** 2)));
157	      }
158	      return { mel: 0.8 * mel + 0.04, xan: 0.25 * smoothstep(0.5, 0.0, t), irid: 0.05 };
159	    },
160	  });
161	  const D2 = medianFin({
162	    name: 'Fin_Dorsal2', s0: 19.2, s1: 33.0, count: 14, a0: 60, a1: 27, dorsal: true, spines: 1, curv: 0.03, notch: 0.07, pleat: 0.05, sag: 0.025,
163	    lengths: [2.9, 3.6, 4.0, 4.2, 4.3, 4.35, 4.4, 4.4, 4.45, 4.5, 4.55, 4.5, 4.35, 3.9], rect: R(0, 1024, 1024, 512), branchT: 0.55, segStart: 0.18,
164	    pigment: (r, n, Lr, len, t, dRay) => {
165	      let mel = 0;
166	      for (let j = 0; j < 9; j++) {
167	        const Lj = 0.42 + j * 0.55 + r * 0.05 + (hash01(r, j, 2, 522) - 0.5) * 0.2;
168	        if (Lj > len * 0.88) break;
169	        if (hash01(r, j, 1, 521) < 0.22) continue;
170	        const ls = 0.09 + 0.08 * hash01(r, j, 3, 523);
171	        mel = Math.max(mel, (0.45 + 0.55 * hash01(r, j, 4, 524)) * Math.exp(-(((Lr - Lj) / ls) ** 2)) * Math.exp(-((dRay / 0.075) ** 2)));
172	      }
173	      return { mel: 0.72 * mel + 0.03, xan: 0.22 * smoothstep(0.6, 0.0, t), irid: 0.05 };
174	    },
175	  });
176	  const AN = medianFin({
177	    name: 'Fin_Anal', s0: 23.7, s1: 33.2, count: 12, a0: -58, a1: -27, dorsal: false, spines: 1, curv: 0.03, notch: 0.07, pleat: 0.05, sag: 0.025,
178	    lengths: [2.1, 2.9, 3.3, 3.5, 3.6, 3.65, 3.7, 3.7, 3.75, 3.8, 3.75, 3.5], rect: R(0, 1536, 1024, 512), branchT: 0.55, segStart: 0.18,
179	    pigment: (r, n, Lr, len, t) => ({ mel: 0.12 * smoothstep(0.72, 0.95, t), xan: 0.14, irid: 0.32 * smoothstep(0.35, 0.0, t) }),
180	  });
181	  return [
182	    caudalFin(R(0, 0, 1024, 1024)),
183	    D1, D2, AN,
184	    pectoralFin(1, R(1024, 0, 1024, 1024)),
185	    pectoralFin(-1, R(1024, 0, 1024, 1024)),
186	    pelvicDisc(R(1536, 1024, 512, 512)),
