193	function rayPoint(def, r, t) {
194	  let p = add(r.base, mul(r.dir, r.len * t));
195	  p = add(p, mul(r.bend, r.len * r.curv * t * t));
196	  p = add(p, mul(def.normal, def.cup * t * t * r.len * 0.12));
197	  return p;
198	}
