  const sh = polyS(PREOPERCLE, y), sm = polyS(OPERCLE, y);
  const u = (s - sh) / Math.max(sm - sh, 0.3);
  const ends = smoothstep(yBot - 0.05, yBot + 0.55, y) * smoothstep(yTop + 0.05, yTop - 0.5, y);
  return smoothstep(0.02, 0.85, u) * ends;
}

