export function bodyWeights(mesh) {
  const list = mesh.verts.map((v) => {
    const [s, y, z] = v.fish;
    const reg = [];
    const wj = clamp(jawWeightBody(v));
    if (wj > 0) reg.push([J.J_jaw, wj]);
    const gy = gapeY(Math.min(s, RICTUS_S));
    if (!v.jawSide && s < RICTUS_S + 0.3 && y > gy - 0.05) {
