  });
  return pack(list, mesh.verts.length);
}

export function interiorWeights(part) {
  const list = part.verts.map((v) => {
    const s = v.fish[0];
    const reg = [];
    const u = v.blend;
    switch (v.zone) {
      case 'mouthUpper':
        reg.push([J.J_premax, 0.8 * smoothstep(0.3, 0.0, u)]);
        reg.push([J.J_head, 1 - 0.8 * smoothstep(0.3, 0.0, u)]);
