        return [[J.J_jaw, jaw], [J.J_hyoid, hy], [J.J_head, Math.max(0, 1 - jaw - hy)]];
      }
      case 'mouthWall':
        return [[J.J_jaw, u * 0.85], [J.J_hyoid, u * 0.1], [J.J_head, 1 - u * 0.95]];
      case 'flapLining':
        reg.push([v.fish[2] >= 0 ? J.J_opercL : J.J_opercR, opercWeight(v.fish)]);
        return combine(reg, s);
      default:
        return combine([], s);
    }
  });
