    } else { for (let t = 0; t < 0.5; t += 1 / 60) update(1 / 60); }
    st.paused = true;
  }

  return {
    update, dart, yawn, flick, paddle, pose,
    anchor: () => root.position,
    setAuto: (v) => { st.auto = v; },
    setPaused: (v) => { st.paused = v; },
    state: st,
  };
}

