99	/** Iris / pupil texture (azimuthal-equidistant projection around the optical axis). */
100	export function paintIris(size = 1024) {
101	  const rgb = new Uint8Array(size * size * 3);
102	  const srgb = (c) => { c = clamp(c); return Math.round(255 * (c <= 0.0031308 ? c * 12.92 : 1.055 * Math.pow(c, 1 / 2.4) - 0.055)); };
103	  for (let py = 0; py < size; py++)
104	    for (let px = 0; px < size; px++) {
105	      const dx = ((px + 0.5) / size) * 2 - 1;
106	      const dy = -(((py + 0.5) / size) * 2 - 1);
107	      const r = Math.min(Math.hypot(dx, dy), 1);
108	      const theta = r * Math.PI;
109	      const psi = Math.atan2(dy, dx);
110	      const lx = Math.sin(theta) * Math.cos(psi), ly = Math.sin(theta) * Math.sin(psi), lz = Math.cos(theta);
111	      const pupilEdge = PUPIL_ANGLE + 0.012 * perlin3(Math.cos(psi) * 3, Math.sin(psi) * 3, 0.5, 5);
112	      let c;
113	      if (theta < pupilEdge) {
114	        c = [0.012, 0.016, 0.02];
