    controls.target.copy(tgt);
    controls.update();
    camera.up.copy(up); camera.lookAt(tgt);
    controls.enabled = false;
    if (sp.nointerior) for (const m of fish.interiors) m.visible = false;
  }, sp);
  await p.waitForTimeout(sp.wait || 3500);
  await p.screenshot({ path: sp.out });
  console.log(sp.out, logs.join(' | ') || 'ok');
  await p.close();
}
