// Head shape metrics straight from the SDF: dorsal-view half width W(s), front-view silhouette, mouth width.
import { field, EYE, section, gapeY, RICTUS_S } from '/home/user/gerupamasini/tools/mahaze/anatomy.mjs';
const eyes = [EYE.center, [EYE.center[0], EYE.center[1], -EYE.center[2]]];
const f = (s, y, z) => { let d = field(s, y, z); for (const c of eyes) d = Math.min(d, Math.hypot(s - c[0], y - c[1], z - c[2]) - EYE.radius); return d; };
const zmax = (s, y) => { let z = 5; if (f(s, y, 0) > 0) return 0; let lo = 0, hi = 5; for (let i = 0; i < 30; i++) { const m = (lo + hi) / 2; if (f(s, y, m) < 0) lo = m; else hi = m; } return lo; };
// dorsal view half width: max over y of the lateral extent
const W = (s) => { let best = 0, by = 0; for (let y = -0.5; y < 7.6; y += 0.05) { const z = zmax(s, y); if (z > best) { best = z; by = y; } } return [best, by]; };
const out = { W: [], front: [] };
let maxW = 0;
for (const s of [0.1, 0.3, 0.5, 0.8, 1.2, 1.6, 2.0, 2.5, 3.0, 3.5, 4.0, 4.5, 5.0, 5.5, 6.0, 7.0, 8.0, 9.0, 10.0, 11.0, 12.0]) {
  const [w, y] = W(s); out.W.push([s, +w.toFixed(3), +y.toFixed(2)]); if (w > maxW) maxW = w;
}
const rict = zmax(RICTUS_S - 0.05, gapeY(RICTUS_S));
console.log('dorsal half width W(s) [s, W, y@max]:');
console.log(out.W.map((r) => r.join(':')).join('  '));
console.log('max half width %s  rictus half width %s  mouth/head %s  eyeSep/head %s', maxW.toFixed(3), rict.toFixed(3), (rict / maxW).toFixed(3), (EYE.center[2] / maxW).toFixed(3));
// front silhouette (max over s<=12 of z at each height) + where the max occurs
const fr = [];
for (let y = -0.2; y <= 7.4; y += 0.4) { let b = 0, bs = 0; for (let s = 0; s <= 12; s += 0.25) { const z = zmax(s, y); if (z > b) { b = z; bs = s; } } fr.push(`${y.toFixed(1)}:${b.toFixed(2)}@${bs}`); }
console.log('front silhouette y:z@s  ' + fr.join('  '));
EOF
