  else if (uDebug == 2) col = back + bgT;
  else if (uDebug == 3) col = vec3(sat(innerScat * 0.25)) + vec3(sat(tauNear.g * 2.0), 0.0, 0.0);
  gl_FragColor = vec4(col, 1.0);
}
