        float mott = 0.5 + 0.5 * sin(mm.x * 0.031 + sin(mm.y * 0.023) * 2.3) * sin(mm.y * 0.027 - mm.x * 0.011);
        vec3 avg = mix(sandA, sandB, 0.42 + 0.2 * mott);
