b="""// Around the eye the projection rays fan out from the eye centre instead of the section origin, so they
// meet the eye dome and the lid fold head-on (a lid that overhangs the cornea window is resolved without
// grazing rays); the origin blends back to the section origin away from the eye and toward the midline.
function eyeZoneW(p0) {
  const c = EYE.center, R = EYE.radius + EYE.skin;
  const d = Math.hypot(p0[0] - c[0], p0[1] - c[1], Math.abs(p0[2]) - c[2]);
  return smoothstep(R + 1.1, R + 0.35, d) * smoothstep(0.12, 0.55, Math.abs(p0[2]));
}
function projectEye(p0, w) {
  const so = rayOrigin(p0[0]);
  const c = [EYE.center[0], EYE.center[1], Math.sign(p0[2]) * EYE.center[2]];
  const o = [so[0] + (c[0] - so[0]) * w, so[1] + (c[1] - so[1]) * w, so[2] + (c[2] - so[2]) * w];
  let dir = [p0[0] - o[0], p0[1] - o[1], p0[2] - o[2]];
  const L = Math.hypot(dir[0], dir[1], dir[2]);
  if (L < 1e-6) return p0.slice();
  dir = [dir[0] / L, dir[1] / L, dir[2] / L];
  const at = (t) => field(o[0] + dir[0] * t, o[1] + dir[1] * t, o[2] + dir[2] * t);
  // outside-in: the first surface met coming from outside is the one seen from outside
  const step = 0.012;
  let prev = L + 2.5, lo = -1, hi = -1;
  for (let t = prev - step; t > 0; t -= step) {
    if (at(t) < 0) { lo = t; hi = prev; break; }
    prev = t;
  }
  // inside the cornea window there is no skin until the socket behind the eyeball: park it there (hidden)
  if (lo < 0) return [o[0] + dir[0] * 0.05, o[1] + dir[1] * 0.05, o[2] + dir[2] * 0.05];
  for (let i = 0; i < 16; i++) {
    const m = 0.5 * (lo + hi);
    if (at(m) > 0) hi = m; else lo = m;
  }
  const t = 0.5 * (lo + hi);
  return [o[0] + dir[0] * t, o[1] + dir[1] * t, o[2] + dir[2] * t];
}

/** Moves a base-loft point onto the sculpted surface along the ray from the section origin. */
export function project(p0) {
  const w = eyeZoneW(p0);
  if (w > 0) return projectEye(p0, w);
  const o = rayOrigin(p0[0]);"""
