    while (hi - lo > 1) { const m = (lo + hi) >> 1; if (sList[m] > s) hi = m; else lo = m; }
    colI[x] = lo;
    colF[x] = (s - sList[lo]) / Math.max(sList[lo + 1] - sList[lo], 1e-9);
  }
