  if (imageViews.has(i)) return;
  const pad = (4 - (off % 4)) % 4;
  if (pad) { parts.push(Buffer.alloc(pad)); off += pad; }
  parts.push(bin.subarray(v.byteOffset, v.byteOffset + v.byteLength));
  remap.set(i, views.length);
  views.push({ ...v, byteOffset: off });
  off += v.byteLength;
});
const newBin = Buffer.concat(parts);
json.bufferViews = views;
for (const a of json.accessors) a.bufferView = remap.get(a.bufferView);
