b=s.index("  return { width: texW, height: texH, albedo, normal: normalMap, orm, pigment, volume, cap };\n}")+len("  return { width: texW, height: texH, albedo, normal: normalMap, orm, pigment, volume, cap };\n}")
new='''  // pigment densities of a colour morph: melanophores as an optical-depth factor plus a diffuse dusky layer
  // over the back and flanks, xanthophores scaled
  const morphMel = (m, hn, col) => 1 - Math.pow(1 - clamp(m), col.melK) * (1 - col.melAdd * (1 - bellyOf(hn)));
  const morphXan = (x, col) => clamp(x * col.xanK);

  // ---------------------------------------------------------------------------
  // Encode maps: normal, ORM and thickness once; albedo and pigment for every colour morph
  log('    encoding …');
  const normalMap = new Uint8Array(nT * 3);
  const orm = new Uint8Array(nT * 3);
  const volume = new Uint8Array(nT * 3);
  const CAV = new Float32Array(nT);
  const morphs = colors.map(() => ({ albedo: new Uint8Array(nT * 3), pigment: new Uint8Array(nT * 3) }));
  const srgb = (c) => {
    c = clamp(c, 0, 1);
    return Math.round(255 * (c <= 0.0031308 ? c * 12.92 : 1.055 * Math.pow(c, 1 / 2.4) - 0.055));
  };
  for (let y = 0; y < texH; y++) {
    const ym = (y - 1 + texH) % texH, yp = (y + 1) % texH;
    for (let x = 0; x < texW; x++) {
      const t = y * texW + x;
      const xm = Math.max(0, x - 1), xp = Math.min(texW - 1, x + 1);
      // tangent-space normal (T = +u, B = image up)
      const poleK = smoothstep(0.3, 0.8, A.px[t]);
      const gx = poleK * (H[y * texW + xp] - H[y * texW + xm]) / ((xp - xm) * A.du[t]);
      const gyUp = poleK * (H[ym * texW + x] - H[yp * texW + x]) / (2 * Math.max(A.dv[t], 0.004));
      let nx = -gx, ny = -gyUp, nz = 1;
      const nl = Math.hypot(nx, ny, nz);
      nx /= nl; ny /= nl; nz /= nl;
      normalMap[t * 3] = Math.round((nx * 0.5 + 0.5) * 255);
      normalMap[t * 3 + 1] = Math.round((ny * 0.5 + 0.5) * 255);
      normalMap[t * 3 + 2] = Math.round((nz * 0.5 + 0.5) * 255);
      // cavity from the height Laplacian (mm^-1)
      // (dv is clamped: near the snout pole the texel height collapses and would blow up the Laplacian)
      const lap = poleK * (H[y * texW + xp] + H[y * texW + xm] - 2 * H[t]) / (A.du[t] * A.du[t]) + poleK *
        (H[ym * texW + x] + H[yp * texW + x] - 2 * H[t]) / Math.max(A.dv[t] * A.dv[t], 1e-4);
      const cavity = clamp(lap * 0.35, 0, 0.35);
      CAV[t] = cavity;

      const s = A.px[t], yy = A.py[t], z = A.pz[t];
      const I = IRI[t];
      colors.forEach((c, ci) => {
        const col = COLORS[c - 1], out = morphs[ci];
        const mel = morphMel(MEL[t], HN[t], col), X = morphXan(XAN[t], col);
        const C = shadeAt(s, yy, z, HN[t], HEAD[t], mel, I, X, GILL[t], cavity, secs[x].w, col);
        out.albedo[t * 3] = srgb(C.r); out.albedo[t * 3 + 1] = srgb(C.g); out.albedo[t * 3 + 2] = srgb(C.b);
        out.pigment[t * 3] = Math.round(mel * 255);
        out.pigment[t * 3 + 1] = Math.round(clamp(I) * 255);
        out.pigment[t * 3 + 2] = Math.round(X * 255);
        // roughness does not depend on the colour: taken from the first morph
        if (ci === 0) {
          const ao = clamp(A.ao[t] * (1 - cavity), 0, 1);
          orm[t * 3] = Math.round(ao * 255);
          orm[t * 3 + 1] = Math.round(clamp(C.rough, 0.12, 0.8) * 255);
          orm[t * 3 + 2] = 0;
        }
      });

      const thk = A.thk[t];
      const trans = clamp(1.1 - thk / 5.0, 0.12, 0.92) * (1 - 0.7 * clamp(MEL[t])) * (1 - 0.45 * I);
      volume[t * 3] = Math.round(trans * 255);
      volume[t * 3 + 1] = Math.round(clamp(thk / 8.0) * 255);
      volume[t * 3 + 2] = 0;
    }
  }
  // ---------------------------------------------------------------------------
  // Snout cap: planar (y, z) projection of the front face, shaded with the same functions. The viewer
  // blends it over the loft UVs where they converge at the snout tip.
  log('    snout cap …');
  const CAP = texW >= 2048 ? 384 : 192;
  const capRect = { y0: -0.2, y1: 4.8, z0: -2.7, z1: 2.7 };
  const caps = colors.map(() => ({ albedo: new Uint8Array(CAP * CAP * 4), pigment: new Uint8Array(CAP * CAP * 3) }));
  const valid = new Uint8Array(CAP * CAP);
  for (let j = 0; j < CAP; j++)
    for (let i = 0; i < CAP; i++) {
      const yy = capRect.y0 + ((j + 0.5) / CAP) * (capRect.y1 - capRect.y0);
      const z = capRect.z0 + ((i + 0.5) / CAP) * (capRect.z1 - capRect.z0);
      // march from in front of the fish toward +s until inside
      let s0 = -1.2, hit = false;
      for (let k = 0; k < 160; k++) { if (field(s0, yy, z) < 0) { hit = true; break; } s0 += 0.025; }
      if (!hit || s0 > 2.6) continue;
      let lo = s0 - 0.025, hi = s0;
      for (let k = 0; k < 12; k++) { const m = 0.5 * (lo + hi); if (field(m, yy, z) < 0) hi = m; else lo = m; }
      const sp = 0.5 * (lo + hi);
      const P = pigmentAt(Math.max(sp, 0.02), yy, z);
      const mel0 = 1 - (1 - P.mel) * (1 - Math.min(spots3D(Math.max(sp, 0.21), yy, z), 0.95));
      const halfW = section(Math.max(sp, 0.05)).w;
      const o = j * CAP + i;
      valid[o] = 1;
      colors.forEach((c, ci) => {
        const col = COLORS[c - 1], out = caps[ci];
        const mel = morphMel(mel0, P.hn, col), X = morphXan(P.xan, col);
        const C = shadeAt(Math.max(sp, 0.02), yy, z, P.hn, P.head, mel, P.iri, X, P.gill, 0, halfW, col);
        out.albedo[o * 4] = srgb(C.r); out.albedo[o * 4 + 1] = srgb(C.g); out.albedo[o * 4 + 2] = srgb(C.b);
        out.albedo[o * 4 + 3] = Math.round(clamp(C.rough, 0.12, 0.8) * 255);
        out.pigment[o * 3] = Math.round(mel * 255); out.pigment[o * 3 + 1] = Math.round(P.iri * 255); out.pigment[o * 3 + 2] = Math.round(X * 255);
      });
    }
  // dilate into the empty border so bilinear / mip filtering never pulls in black
  for (let pass = 0; pass < 12; pass++) {
    const next = valid.slice();
    for (let j = 0; j < CAP; j++)
      for (let i = 0; i < CAP; i++) {
        const o = j * CAP + i;
        if (valid[o]) continue;
        for (const [di, dj] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
          const ii = i + di, jj = j + dj;
          if (ii < 0 || jj < 0 || ii >= CAP || jj >= CAP) continue;
          const q = jj * CAP + ii;
          if (!valid[q]) continue;
          for (const out of caps) {
            for (let c = 0; c < 4; c++) out.albedo[o * 4 + c] = out.albedo[q * 4 + c];
            for (let c = 0; c < 3; c++) out.pigment[o * 3 + c] = out.pigment[q * 3 + c];
          }
          next[o] = 1;
          break;
        }
      }
    valid.set(next);
  }
  return {
    width: texW, height: texH, normal: normalMap, orm, volume,
    // per colour morph: body albedo + pigment and the snout cap
    colors: colors.map((c, ci) => ({ color: c, albedo: morphs[ci].albedo, pigment: morphs[ci].pigment, cap: { size: CAP, albedo: caps[ci].albedo, pigment: caps[ci].pigment, rect: capRect } })),
  };
}'''
s=s[:a]+new+s[b:]
open(p,'w').write(s)
