// Free margin of the gill cover (operculum + subopercle), top → bottom (head length ≈ 28.5 % SL).
export const OPERCLE = [[10.0, 5.1], [10.8, 4.62], [11.4, 3.8], [11.7, 2.8], [11.55, 1.8], [11.1, 0.95], [10.4, 0.38], [9.6, 0.08]];
