  [[7.1, 4.8], [7.7, 3.62], [8.0, 2.5], [7.8, 1.5], [7.1, 0.75], [6.2, 0.32]],
  [[7.4, 4.95], [8.0, 3.7], [8.3, 2.5], [8.1, 1.5], [7.4, 0.75], [6.5, 0.32]],
