// Rig pivots (fish space, mm)
export const PIVOTS = {
  jaw: pick([5.1, 0.95, 0], [4.15, 0.95, 0]),
  premax: pick([0.9, 2.6, 0], [1.0, 3.05, 0]),
  hyoid: pick([6.0, 0.45, 0], [5.4, 0.45, 0]),
  opercTop: [9.4, 4.9],
  opercBottom: [9.6, 0.45],
