# Convert a Claude Code session transcript (.jsonl) into a readable Markdown log.
# usage: python3 tomd.py transcript.jsonl out.md
#   user and assistant messages in order with timestamps (JST); tool calls as name + one-line summary,
#   tool output reduced to its first line; thinking blocks, images and harness records are omitted.
import json, sys, re
from datetime import datetime, timezone, timedelta

SRC, OUT = sys.argv[1], sys.argv[2]
JST = timezone(timedelta(hours=9))


def ts(s):
    if not s:
        return ''
    t = datetime.fromisoformat(s.replace('Z', '+00:00')).astimezone(JST)
    return t.strftime('%Y-%m-%d %H:%M:%S')


def short(s, n=140):
    s = re.sub(r'\s+', ' ', str(s)).strip()
    return s if len(s) <= n else s[: n - 1] + '…'


def clean_user_text(s):
    # harness-injected blocks are not part of what the user typed
    s = re.sub(r'<system-reminder>.*?</system-reminder>', '', s, flags=re.S)
    return s.strip()


def tool_summary(name, inp):
    g = lambda k: inp.get(k) if isinstance(inp, dict) else None
    if name == 'Bash':
        return g('description') or short(g('command'), 100)
    if name in ('Read', 'Write', 'Edit', 'NotebookEdit'):
        p = g('file_path') or g('notebook_path') or ''
        extra = ''
        if name == 'Read' and (g('offset') or g('limit')):
            extra = f" (offset {g('offset') or 0}, limit {g('limit') or '-'})"
        return p + extra
    if name in ('Grep', 'Glob'):
        return f"`{short(g('pattern'), 80)}`" + (f" in {g('path')}" if g('path') else '')
    if name == 'Artifact':
        return ' '.join(str(x) for x in [g('action') or 'publish', g('label') or '', g('url') or g('file_path') or ''] if x)
    if name == 'Skill':
        return g('skill') or ''
    if name == 'SendUserFile':
        return ', '.join(str(f).split('/')[-1] for f in (g('files') or []))
    if name == 'Agent':
        return g('description') or ''
    if name == 'AskUserQuestion':
        q = (g('questions') or [{}])[0]
        return short(q.get('question', ''), 120)
    if name == 'ToolSearch':
        return g('query') or ''
    if isinstance(inp, dict) and inp:
        parts = [f'{k}={short(v, 50)}' for k, v in list(inp.items())[:2] if not isinstance(v, (dict, list))]
        return ', '.join(parts)
    return ''


def result_note(c, is_error):
    lines = []
    imgs = 0
    if isinstance(c, str):
        lines = c.splitlines()
    elif isinstance(c, list):
        for b in c:
            if isinstance(b, dict):
                if b.get('type') == 'text':
                    lines += str(b.get('text', '')).splitlines()
                elif b.get('type') == 'image':
                    imgs += 1
    lines = [l for l in lines if l.strip()]
    note = ''
    if lines:
        note = short(lines[0], 120)
        if len(lines) > 1:
            note += f' …（他 {len(lines) - 1} 行省略）'
    if imgs:
        note = (note + ' ' if note else '') + f'[画像 {imgs} 枚]'
    if is_error:
        note = 'エラー: ' + (note or '(内容なし)')
    return note


rows = [json.loads(l) for l in open(SRC, encoding='utf-8') if l.strip()]

# pass 1: tool results by id
results = {}
for o in rows:
    if o.get('type') == 'user' and isinstance(o.get('message', {}).get('content'), list):
        for b in o['message']['content']:
            if isinstance(b, dict) and b.get('type') == 'tool_result':
                results[b.get('tool_use_id')] = result_note(b.get('content'), b.get('is_error'))

out = []
n_user = n_user_queued = n_summary = n_asst = n_tools = 0
first_ts = last_ts = None
seen = set()
in_assistant = False  # inside a run of assistant entries (header already written)

for o in rows:
    u = o.get('uuid')
    if u and u in seen:
        continue
    if u:
        seen.add(u)
    t = o.get('type')
    stamp = ts(o.get('timestamp'))
    if o.get('timestamp'):
        first_ts = first_ts or stamp
        last_ts = stamp

    if t == 'user':
        m = o.get('message', {})
        c = m.get('content')
        if o.get('isMeta'):
            continue
        if o.get('isCompactSummary'):
            n_summary += 1
            text = c if isinstance(c, str) else '\n'.join(b.get('text', '') for b in c if isinstance(b, dict))
            out.append(f'\n---\n\n### 🗂 コンテキスト要約（{stamp}）\n\n<details><summary>会話が長くなったため、それまでの内容が要約されました（クリックで展開）</summary>\n\n{text.strip()}\n\n</details>\n')
            in_assistant = False
            continue
        if isinstance(c, str):
            text, imgs = clean_user_text(c), 0
        elif isinstance(c, list):
            if all(isinstance(b, dict) and b.get('type') == 'tool_result' for b in c):
                continue
            text = clean_user_text('\n'.join(b.get('text', '') for b in c if isinstance(b, dict) and b.get('type') == 'text'))
            imgs = sum(1 for b in c if isinstance(b, dict) and b.get('type') == 'image')
        else:
            continue
        if not text and not imgs:
            continue
        n_user += 1
        img = f'\n\n*［画像 {imgs} 枚添付］*' if imgs else ''
        out.append(f'\n---\n\n### 👤 ユーザー（{stamp}）\n\n{text}{img}\n')
        in_assistant = False

    elif t == 'attachment' and o.get('attachment', {}).get('type') == 'queued_command':
        p = o['attachment'].get('prompt')
        if isinstance(p, str):
            text, imgs = clean_user_text(p), 0
        else:
            text = clean_user_text('\n'.join(b.get('text', '') for b in (p or []) if isinstance(b, dict) and b.get('type') == 'text'))
            imgs = sum(1 for b in (p or []) if isinstance(b, dict) and b.get('type') == 'image')
        if not text and not imgs:
            continue
        n_user += 1
        n_user_queued += 1
        img = f'\n\n*［画像 {imgs} 枚添付］*' if imgs else ''
        out.append(f'\n---\n\n### 👤 ユーザー（{stamp}・作業中に送信）\n\n{text}{img}\n')
        in_assistant = False

    elif t == 'assistant':
        c = o.get('message', {}).get('content')
        if not isinstance(c, list):
            continue
        for b in c:
            if not isinstance(b, dict):
                continue
            if b.get('type') == 'text' and b.get('text', '').strip():
                if not in_assistant:
                    out.append(f'\n### 🤖 アシスタント（{stamp}）\n')
                    in_assistant = True
                n_asst += 1
                out.append('\n' + b['text'].strip() + '\n')
            elif b.get('type') == 'tool_use':
                if not in_assistant:
                    out.append(f'\n### 🤖 アシスタント（{stamp}）\n')
                    in_assistant = True
                n_tools += 1
                name = b.get('name', '?')
                s = tool_summary(name, b.get('input'))
                r = results.get(b.get('id'), '')
                line = f'- 🔧 `{name}`' + (f' — {short(s, 160)}' if s else '')
                if r:
                    line += f'\n  - → {r}'
                out.append(line + '\n')

head = f"""# 会話ログ — マハゼ 3D モデル（Claude Code セッション）

- セッション ID: `{rows[0].get('sessionId', '')}`
- 期間: {first_ts} 〜 {last_ts}（時刻はすべて日本時間 JST）
- ユーザー発言: {n_user} 件（うち作業中に送信 {n_user_queued} 件）／アシスタント発言: {n_asst} 件／ツール呼び出し: {n_tools} 件／コンテキスト要約: {n_summary} 件
- 元データ: 同じフォルダの `.jsonl`（Claude Code の生ログ）

**表記について**: ツール呼び出しは「ツール名 — 要約」と、結果の最初の 1 行だけを載せ、長い出力は省略しています。アシスタントの思考（thinking）、画像データ、システムが自動で挿入した記録（リマインダー、ツール定義など）は載せていません。

"""
open(OUT, 'w', encoding='utf-8').write(head + ''.join(out))
print(json.dumps({'user': n_user, 'user_queued': n_user_queued, 'assistant_text': n_asst, 'tool_calls': n_tools, 'summaries': n_summary, 'first': first_ts, 'last': last_ts}, ensure_ascii=False))

