# Copy a Claude Code transcript with embedded image data removed and the user's email redacted.
# usage: python3 sanitize.py in.jsonl out.jsonl
# Redaction works on the parsed string values (never on the serialized JSON), so escapes stay valid.
import json, sys, re
src, dst = sys.argv[1], sys.argv[2]
# the address and any fragment of it (also inside logged shell commands, possibly regex-escaped)
EMAIL_RE = re.compile(r'[\w.+\\-]*[redacted][\w.+\\-]*(?:@[\w.-]+)?|(?:dc\\?\.)?[redacted](?:\\?\.ac\\?\.jp)?', re.I)
n_img = n_red = 0


def red(s):
    global n_red
    s2, k = EMAIL_RE.subn('[redacted]', s)
    n_red += k
    return s2


def clean(x):
    global n_img
    if isinstance(x, dict):
        if x.get('type') == 'image' and isinstance(x.get('source'), dict):
            n_img += 1
            return {'type': 'image', 'source': {'type': 'omitted', 'note': 'image data removed from export'}}
        if isinstance(x.get('base64'), str) and len(x['base64']) > 1000:
            n_img += 1
            x = dict(x)
            x['base64'] = '(image data removed from export)'
        return {red(k): clean(v) for k, v in x.items()}
    if isinstance(x, list):
        return [clean(v) for v in x]
    if isinstance(x, str):
        return red(x)
    return x


lines = 0
with open(src, encoding='utf-8') as f, open(dst, 'w', encoding='utf-8') as g:
    for line in f:
        if not line.strip():
            continue
        g.write(json.dumps(clean(json.loads(line)), ensure_ascii=False) + '\n')
        lines += 1
print(json.dumps({'lines': lines, 'images_removed': n_img, 'redactions': n_red}))

